FILES = {'src/sofia/personality/probe.py': '"""Batch G4: explicit, bounded-case personality observation harness.\n\nThis harness preserves raw responses and errors. It does not grade, alter,\npost-process, approve, or guarantee a language model\'s personality fidelity.\nCalling it with a live engine may block for the provider\'s configured duration;\nmax_cases limits count, NOT wall-clock time. No live engine is created here.\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom hashlib import sha256\nfrom time import perf_counter\n\nfrom sofia.cognition.assembler import CognitiveContextAssembler\nfrom sofia.cognition.context import CognitiveContext\nfrom sofia.cognition.engine import CognitiveEngine\nfrom sofia.cognition.model import (\n    CognitiveMessage,\n    CognitiveRequest,\n    CognitiveResponse,\n    CognitiveRole,\n)\nfrom sofia.personality.model import PersonalityProfile\n\n\n@dataclass(frozen=True)\nclass PersonalityProbeCase:\n    label: str\n    user_text: str\n\n    def __post_init__(self) -> None:\n        if not isinstance(self.label, str) or not self.label.strip():\n            raise ValueError("Probe case label must be a nonempty string.")\n        if not isinstance(self.user_text, str) or not self.user_text.strip():\n            raise ValueError("Probe case user_text must be a nonempty string.")\n\n\n@dataclass(frozen=True)\nclass PersonalityProbeObservation:\n    """A raw observation, never a pass/fail personality assessment."""\n\n    label: str\n    request_sha256: str\n    raw_response: str | None\n    elapsed_seconds: float\n    error_type: str | None\n    error_message: str | None\n\n    @property\n    def succeeded(self) -> bool:\n        return self.error_type is None\n\n\ndef observe_personality_cases(\n    profile: PersonalityProfile,\n    engine: CognitiveEngine,\n    cases: tuple[PersonalityProbeCase, ...],\n    *,\n    max_cases: int,\n) -> tuple[PersonalityProbeObservation, ...]:\n    """Observe explicit cases sequentially, retaining failures and raw text.\n\n    Refuses excess cases instead of truncating them without disclosure.\n    Exception details can contain provider data: review before sharing logs.\n    """\n    if not isinstance(profile, PersonalityProfile):\n        raise TypeError("profile must be a PersonalityProfile.")\n    if not isinstance(engine, CognitiveEngine):\n        raise TypeError("engine must be a CognitiveEngine.")\n    if not isinstance(cases, tuple) or not cases:\n        raise ValueError("cases must be a nonempty tuple.")\n    if type(max_cases) is not int or max_cases <= 0:\n        raise ValueError("max_cases must be a positive integer.")\n    if len(cases) > max_cases:\n        raise ValueError("Case count exceeds max_cases; no generation performed.")\n    if any(not isinstance(case, PersonalityProbeCase) for case in cases):\n        raise TypeError("cases must contain PersonalityProbeCase instances.")\n    labels = [case.label for case in cases]\n    if len(set(labels)) != len(labels):\n        raise ValueError("Probe case labels must be unique.")\n\n    assembler = CognitiveContextAssembler()\n    observations: list[PersonalityProbeObservation] = []\n    for case in cases:\n        source = CognitiveRequest(messages=(\n            CognitiveMessage(role=CognitiveRole.USER, content=case.user_text),\n        ))\n        assembled = assembler.assemble(\n            CognitiveContext(request=source, personality=profile)\n        )\n        # Hash is a comparison aid, not proof of truth or an authenticity signature.\n        payload = "".join(\n            f"{len(message.role.value)}:{message.role.value}"\n            f"{len(message.content)}:{message.content}"\n            for message in assembled.messages\n        )\n        request_sha256 = sha256(payload.encode("utf-8")).hexdigest()\n        began = perf_counter()\n        raw_response: str | None = None\n        error_type: str | None = None\n        error_message: str | None = None\n        try:\n            result = engine.respond(assembled)\n            if not isinstance(result, CognitiveResponse):\n                raise TypeError("Engine returned a non-CognitiveResponse value.")\n            raw_response = result.content\n        except Exception as exc:\n            error_type = type(exc).__name__\n            error_message = str(exc)\n        observations.append(PersonalityProbeObservation(\n            label=case.label,\n            request_sha256=request_sha256,\n            raw_response=raw_response,\n            elapsed_seconds=perf_counter() - began,\n            error_type=error_type,\n            error_message=error_message,\n        ))\n    return tuple(observations)\n', 'src/sofia/distributed/reachability.py': '"""Engineering 22D: passive, evidence-based peer reachability reconciliation.\n\nNo probes, sockets, authentication, node discovery, or remote operations.\nAn expected state is a human expectation, never observed liveness.\nSource names are caller supplied and do not prove signal independence.\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom datetime import datetime, timedelta\nfrom enum import Enum\n\nfrom sofia.distributed.knowledge import PeerKnowledgeSnapshot\nfrom sofia.distributed.model import NodeObservation, NodeReachability\n\n\nclass ExpectedPeerState(str, Enum):\n    UNSPECIFIED = "unspecified"\n    EXPECTED_AVAILABLE = "expected_available"\n    EXPECTED_UNAVAILABLE = "expected_unavailable"\n\n\nclass ReachabilityDiscrepancy(str, Enum):\n    NONE = "none"\n    EXPECTED_AVAILABLE_NOT_CONFIRMED = "expected_available_not_confirmed"\n    EXPECTED_UNAVAILABLE_BUT_REACHABLE = "expected_unavailable_but_reachable"\n    CONFLICTING_EVIDENCE = "conflicting_evidence"\n\n\n@dataclass(frozen=True)\nclass PeerReachabilityAssessment:\n    """Original evidence remains available; no \'offline\' verdict is possible."""\n\n    node_id: object\n    expected: ExpectedPeerState\n    reachability: NodeReachability\n    discrepancy: ReachabilityDiscrepancy\n    current: tuple[NodeObservation, ...]\n    stale: tuple[NodeObservation, ...]\n    future: tuple[NodeObservation, ...]\n\n\ndef assess_peer_reachability(\n    peer: PeerKnowledgeSnapshot,\n    *,\n    observations: tuple[NodeObservation, ...] = (),\n    now: datetime,\n    max_age: timedelta,\n    expected: ExpectedPeerState = ExpectedPeerState.UNSPECIFIED,\n) -> PeerReachabilityAssessment:\n    """Reconcile the latest *current* caller-supplied evidence per source.\n\n    The 22C latest observation is included automatically. Contradictory\n    evidence yields DEGRADED, not a fabricated online/offline decision.\n    """\n    if not isinstance(peer, PeerKnowledgeSnapshot):\n        raise TypeError("peer must be a PeerKnowledgeSnapshot.")\n    if not isinstance(observations, tuple):\n        raise TypeError("observations must be a tuple.")\n    if not isinstance(now, datetime):\n        raise TypeError("now must be a datetime.")\n    if now.tzinfo is None or now.utcoffset() is None:\n        raise ValueError("now must be timezone-aware.")\n    if not isinstance(max_age, timedelta):\n        raise TypeError("max_age must be a timedelta.")\n    if max_age <= timedelta(0):\n        raise ValueError("max_age must be positive.")\n    if not isinstance(expected, ExpectedPeerState):\n        raise TypeError("expected must be an ExpectedPeerState.")\n\n    node_id = peer.enrollment.node.node_id\n    all_observations = ((peer.observation,) if peer.observation is not None else ()) + observations\n    latest: dict[str, NodeObservation] = {}\n    stale: list[NodeObservation] = []\n    future: list[NodeObservation] = []\n    for item in all_observations:\n        if not isinstance(item, NodeObservation):\n            raise TypeError("observations must contain NodeObservation instances.")\n        if item.node_id != node_id:\n            raise ValueError("Observation does not belong to the enrolled node.")\n        if item.observed_at > now:\n            future.append(item)\n        elif now - item.observed_at > max_age:\n            stale.append(item)\n        else:\n            previous = latest.get(item.source)\n            if previous is None or item.observed_at > previous.observed_at:\n                latest[item.source] = item\n            elif item.observed_at == previous.observed_at and item != previous:\n                raise ValueError("Conflicting evidence from one source has an equal timestamp.")\n\n    current = tuple(latest[source] for source in sorted(latest))\n    values = {item.reachability for item in current}\n    if NodeReachability.DEGRADED in values or (\n        NodeReachability.REACHABLE in values and NodeReachability.UNREACHABLE in values\n    ):\n        effective = NodeReachability.DEGRADED\n    elif NodeReachability.REACHABLE in values:\n        effective = NodeReachability.REACHABLE\n    elif NodeReachability.UNREACHABLE in values:\n        effective = NodeReachability.UNREACHABLE\n    else:\n        effective = NodeReachability.UNKNOWN\n\n    if effective is NodeReachability.DEGRADED:\n        discrepancy = ReachabilityDiscrepancy.CONFLICTING_EVIDENCE\n    elif expected is ExpectedPeerState.EXPECTED_AVAILABLE and effective is not NodeReachability.REACHABLE:\n        discrepancy = ReachabilityDiscrepancy.EXPECTED_AVAILABLE_NOT_CONFIRMED\n    elif expected is ExpectedPeerState.EXPECTED_UNAVAILABLE and effective is NodeReachability.REACHABLE:\n        discrepancy = ReachabilityDiscrepancy.EXPECTED_UNAVAILABLE_BUT_REACHABLE\n    else:\n        discrepancy = ReachabilityDiscrepancy.NONE\n\n    return PeerReachabilityAssessment(\n        node_id=node_id,\n        expected=expected,\n        reachability=effective,\n        discrepancy=discrepancy,\n        current=current,\n        stale=tuple(stale),\n        future=tuple(future),\n    )\n', 'test/test_personality_probe.py': '"""Batch G4: offline observation harness tests; no Ollama calls."""\nimport pytest\n\nfrom sofia.cognition.engine import CognitiveEngine\nfrom sofia.cognition.model import CognitiveResponse\nfrom sofia.personality.model import PersonalityProfile\nfrom sofia.personality.probe import (\n    PersonalityProbeCase,\n    observe_personality_cases,\n)\n\n\nclass RecordingEngine(CognitiveEngine):\n    def __init__(self, responses):\n        self.requests = []\n        self.responses = list(responses)\n\n    def respond(self, request):\n        self.requests.append(request)\n        result = self.responses.pop(0)\n        if isinstance(result, Exception):\n            raise result\n        return result\n\n\ndef test_observations_preserve_raw_text_and_personality_context():\n    engine = RecordingEngine([CognitiveResponse(content="I am a generic assistant.")])\n    profile = PersonalityProfile(name="Sofía", traits=("playful", "rigorous"))\n    (observation,) = observe_personality_cases(profile, engine, (\n        PersonalityProbeCase("identity", "Who are you?"),\n    ), max_cases=1)\n    assert observation.succeeded\n    assert observation.raw_response == "I am a generic assistant."\n    assert observation.error_type is None\n    assert len(observation.request_sha256) == 64\n    assert observation.elapsed_seconds >= 0\n    assert "Traits: playful, rigorous" in engine.requests[0].messages[0].content\n    assert engine.requests[0].messages[-1].content == "Who are you?"\n    # The harness does not pretend that this generic response passed fidelity.\n    assert not hasattr(observation, "personality_score")\n\n\ndef test_each_case_retains_errors_without_erasing_other_responses():\n    engine = RecordingEngine([RuntimeError("provider unavailable"), CognitiveResponse(content="Hi")])\n    observations = observe_personality_cases(PersonalityProfile(name="Sofía"), engine, (\n        PersonalityProbeCase("first", "Question one"),\n        PersonalityProbeCase("second", "Question two"),\n    ), max_cases=2)\n    assert len(observations) == 2\n    assert observations[0].raw_response is None\n    assert observations[0].error_type == "RuntimeError"\n    assert observations[0].error_message == "provider unavailable"\n    assert observations[1].raw_response == "Hi"\n    assert observations[1].succeeded\n\n\ndef test_case_limit_and_duplicate_labels_fail_before_generation():\n    engine = RecordingEngine([])\n    profile = PersonalityProfile(name="Sofía")\n    case = PersonalityProbeCase("identity", "Who are you?")\n    with pytest.raises(ValueError, match="exceeds max_cases"):\n        observe_personality_cases(profile, engine, (case, case), max_cases=1)\n    with pytest.raises(ValueError, match="unique"):\n        observe_personality_cases(profile, engine, (case, case), max_cases=2)\n    assert engine.requests == []\n\n\n@pytest.mark.parametrize("limit", [0, -1, True, "2"])\ndef test_invalid_case_limit_rejected(limit):\n    with pytest.raises(ValueError, match="max_cases"):\n        observe_personality_cases(PersonalityProfile(name="Sofía"), RecordingEngine([]),\n                                  (PersonalityProbeCase("x", "Hi"),), max_cases=limit)\n\n\ndef test_request_digest_is_repeatable_for_same_input():\n    profile = PersonalityProfile(name="Sofía", traits=("direct",))\n    case = (PersonalityProbeCase("identity", "Who are you?"),)\n    first = observe_personality_cases(profile, RecordingEngine([CognitiveResponse(content="One")]),\n                                      case, max_cases=1)\n    second = observe_personality_cases(profile, RecordingEngine([CognitiveResponse(content="Two")]),\n                                       case, max_cases=1)\n    assert first[0].request_sha256 == second[0].request_sha256\n    assert first[0].raw_response != second[0].raw_response\n\n\ndef test_engine_invalid_response_is_recorded_as_failure():\n    result = observe_personality_cases(PersonalityProfile(name="Sofía"),\n        RecordingEngine([object()]), (PersonalityProbeCase("x", "Hello"),), max_cases=1)\n    assert result[0].error_type == "TypeError"\n    assert result[0].raw_response is None\n', 'test/test_distributed_reachability.py': '"""Engineering 22D evidence fusion tests; no sockets or network probes."""\nfrom dataclasses import FrozenInstanceError\nfrom datetime import datetime, timedelta, timezone\nfrom uuid import uuid4\n\nimport pytest\n\nfrom sofia.distributed.identity import NodeEnrollment, fingerprint_public_key\nfrom sofia.distributed.knowledge import PeerKnowledge\nfrom sofia.distributed.model import DistributedNode, NodeObservation, NodeReachability\nfrom sofia.distributed.reachability import (\n    ExpectedPeerState, ReachabilityDiscrepancy, assess_peer_reachability,\n)\n\nNOW = datetime(2026, 9, 20, 12, tzinfo=timezone.utc)\nAGE = timedelta(minutes=5)\n\n\ndef fixture_peer(base_observation=None):\n    node = DistributedNode(uuid4(), "Artemis")\n    enrollment = NodeEnrollment(\n        node=node, public_key_sha256=fingerprint_public_key(b"example-key"),\n        provisioned_at=NOW, recorded_by="operator",\n    )\n    peers = PeerKnowledge(AGE)\n    peers.enroll(enrollment)\n    if base_observation is not None:\n        peers.record(base_observation)\n    return peers.snapshot(node.node_id, now=NOW)\n\n\ndef signal(peer, source, state, at=NOW):\n    return NodeObservation(\n        node_id=peer.enrollment.node.node_id,\n        observed_at=at, source=source, reachability=state,\n        evidence=(f"Reported by {source}",),\n    )\n\n\ndef assess(peer, *items, expected=ExpectedPeerState.UNSPECIFIED, now=NOW):\n    return assess_peer_reachability(peer, observations=items, now=now,\n                                    max_age=AGE, expected=expected)\n\n\ndef test_missing_signals_are_unknown_even_when_expected_online():\n    peer = fixture_peer()\n    result = assess(peer, expected=ExpectedPeerState.EXPECTED_AVAILABLE)\n    assert result.reachability is NodeReachability.UNKNOWN\n    assert result.discrepancy is ReachabilityDiscrepancy.EXPECTED_AVAILABLE_NOT_CONFIRMED\n    assert result.current == ()\n    assert not hasattr(result, "authorized")\n\n\ndef test_current_reachable_signal_does_not_grant_authority():\n    peer = fixture_peer()\n    result = assess(peer, signal(peer, "tcp", NodeReachability.REACHABLE))\n    assert result.reachability is NodeReachability.REACHABLE\n    assert result.discrepancy is ReachabilityDiscrepancy.NONE\n    assert not hasattr(result, "authenticated")\n    assert not hasattr(result, "execute")\n    with pytest.raises(FrozenInstanceError):\n        result.reachability = NodeReachability.UNKNOWN\n\n\ndef test_failed_probe_is_unreachable_not_offline():\n    peer = fixture_peer()\n    result = assess(peer, signal(peer, "tcp", NodeReachability.UNREACHABLE),\n                    expected=ExpectedPeerState.EXPECTED_AVAILABLE)\n    assert result.reachability is NodeReachability.UNREACHABLE\n    assert result.discrepancy is ReachabilityDiscrepancy.EXPECTED_AVAILABLE_NOT_CONFIRMED\n    assert "offline" not in {item.value for item in NodeReachability}\n\n\ndef test_conflicting_sources_report_degraded_and_keep_evidence():\n    peer = fixture_peer()\n    result = assess(peer, signal(peer, "tcp", NodeReachability.UNREACHABLE),\n                    signal(peer, "service", NodeReachability.REACHABLE))\n    assert result.reachability is NodeReachability.DEGRADED\n    assert result.discrepancy is ReachabilityDiscrepancy.CONFLICTING_EVIDENCE\n    assert len(result.current) == 2\n\n\ndef test_latest_per_source_wins_regardless_of_input_order():\n    peer = fixture_peer()\n    old = signal(peer, "tcp", NodeReachability.UNREACHABLE, NOW - timedelta(seconds=30))\n    new = signal(peer, "tcp", NodeReachability.REACHABLE)\n    assert assess(peer, old, new).reachability is NodeReachability.REACHABLE\n    assert assess(peer, new, old).current == (new,)\n\n\ndef test_stale_and_future_evidence_cannot_claim_current_reachability():\n    peer = fixture_peer()\n    old = signal(peer, "tcp", NodeReachability.REACHABLE, NOW - AGE - timedelta(seconds=1))\n    future = signal(peer, "service", NodeReachability.REACHABLE, NOW + timedelta(seconds=1))\n    result = assess(peer, old, future)\n    assert result.reachability is NodeReachability.UNKNOWN\n    assert result.stale == (old,)\n    assert result.future == (future,)\n\n\ndef test_expectation_is_metadata_not_observed_status():\n    peer = fixture_peer()\n    observed = signal(peer, "tcp", NodeReachability.REACHABLE)\n    result = assess(peer, observed, expected=ExpectedPeerState.EXPECTED_UNAVAILABLE)\n    assert result.reachability is NodeReachability.REACHABLE\n    assert result.discrepancy is ReachabilityDiscrepancy.EXPECTED_UNAVAILABLE_BUT_REACHABLE\n\n\ndef test_22c_snapshot_evidence_is_automatically_included():\n    node = DistributedNode(uuid4(), "Eos")\n    enrollment = NodeEnrollment(node, fingerprint_public_key(b"different-key"), NOW, "operator")\n    knowledge = PeerKnowledge(AGE)\n    knowledge.enroll(enrollment)\n    record = NodeObservation(node.node_id, NOW, "service", NodeReachability.REACHABLE,\n                             evidence=("Service responded",))\n    knowledge.record(record)\n    peer = knowledge.snapshot(node.node_id, now=NOW)\n    result = assess(peer)\n    assert result.current == (record,)\n    assert result.reachability is NodeReachability.REACHABLE\n\n\ndef test_rejects_mismatched_node_and_timestamp_conflict():\n    peer = fixture_peer()\n    foreign = NodeObservation(uuid4(), NOW, "tcp", NodeReachability.UNKNOWN)\n    with pytest.raises(ValueError, match="enrolled node"):\n        assess(peer, foreign)\n    first = signal(peer, "tcp", NodeReachability.REACHABLE)\n    conflicting = signal(peer, "tcp", NodeReachability.UNREACHABLE)\n    with pytest.raises(ValueError, match="Conflicting"):\n        assess(peer, first, conflicting)\n\n\n@pytest.mark.parametrize("invalid", [datetime(2026, 9, 20, 12), None])\ndef test_invalid_clock_rejected(invalid):\n    with pytest.raises((ValueError, TypeError)):\n        assess_peer_reachability(fixture_peer(), now=invalid, max_age=AGE)\n\n\ndef test_no_expected_claim_from_stale_snapshot():\n    peer = fixture_peer()\n    old = signal(peer, "tcp", NodeReachability.REACHABLE, NOW - AGE - timedelta(seconds=1))\n    result = assess(peer, old, expected=ExpectedPeerState.EXPECTED_AVAILABLE)\n    assert result.reachability is NodeReachability.UNKNOWN\n    assert result.discrepancy is ReachabilityDiscrepancy.EXPECTED_AVAILABLE_NOT_CONFIRMED\n', 'docs/development/batch-g4-and-22d.md': '# Batch G4 and Engineering 22D checkpoint\n\n**Status:** implementation prepared for local verification. Neither full batch is complete. This checkpoint follows G1–G3 and 22A–22C.\n\n## G4: explicit observational personality probes\n\n`sofia.personality.probe.observe_personality_cases` accepts the existing personality profile, an explicitly supplied cognitive engine, named user questions, and a positive `max_cases`. It assembles the ordinary personality context and captures a digest of the full role-labeled request, raw provider/engine text, elapsed time, and per-case errors. Too many or duplicate cases are rejected before any inference. It **does not grade**, rewrite outputs, automatically change providers, or create a live engine. A limit on case count is **not a wall-clock timeout**. Mock tests establish only mechanics; eventual real-model responses require an explicitly chosen, timed, locally supervised run.\n\nTests include an intentionally generic answer that is retained as-is. That is evidence of an answer, **not** evidence that the personality contract was followed. No claim about canonical identity fidelity can be inferred from presence of source instructions alone. Review raw texts and provider error messages before sharing or committing them.\n\n## 22D: reconcile peer reachability evidence\n\n`sofia.distributed.reachability.assess_peer_reachability` takes the 22C enrolled-peer snapshot plus explicit caller-supplied observations, a timezone-aware clock, and a positive freshness window. The assessment selects the latest current observation per source; retains stale and future evidence separately; reports conflicting current reachable/unreachable observations as `DEGRADED`; and distinguishes expected availability from actual observed reachability. `UNREACHABLE` records failed observation, **never a verified offline machine**. Source strings do not establish signal independence. It does not scan, contact, authenticate, trust, authorize, or operate any device.\n\n## Local verification\n\n```powershell\npytest -q test/test_personality.py test/test_personality_embodiment_contract.py test/test_personality_pipeline.py test/test_personality_expression_boundary.py test/test_personality_provider_path.py test/test_personality_probe.py test/test_distributed_node_contract.py test/test_distributed_identity.py test/test_distributed_peer_knowledge.py test/test_distributed_reachability.py\npytest -q -m "not integration"\ngit diff --check\ngit status --short\n```\n\nOnly the first command is a focused gate. The broader non-integration suite can take many minutes; report its actual result. All G/22 files remain uncommitted until an approved, reviewed checkpoint. Stage exact intended files, never `git add .` with database, log, or installer scripts present.\n'}


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Preflight without writing")
    args = parser.parse_args()
    root = subprocess.run(
        ["git", "rev-parse", "--show-toplevel"],
        capture_output=True, text=True, check=False,
    )
    if root.returncode or Path(root.stdout.strip()).resolve() != Path.cwd().resolve():
        raise SystemExit("Run from the SofiaAdaLyra Git root; no changes made.")
    missing = [path for path in PREREQUISITES if not Path(path).is_file()]
    if missing:
        raise SystemExit(f"Missing prior G/22 prerequisite files: {missing}. No changes made.")
    collisions = [path for path in FILES if Path(path).exists()]
    if collisions:
        raise SystemExit(f"Targets exist; refusing to overwrite: {collisions}. No changes made.")
    for name, content in FILES.items():
        if name.endswith(".py"):
            ast.parse(content, filename=name)
    print("Preflight OK. Five new files; no existing-file edits:")
    for name in FILES:
        print(f"  {name}")
    if args.check:
        print("--check: no files changed.")
        return
    written: list[Path] = []
    try:
        for name, content in FILES.items():
            path = Path(name)
            path.parent.mkdir(parents=True, exist_ok=True)
            with path.open("x", encoding="utf-8", newline="\n") as stream:
                stream.write(content)
            written.append(path)
    except Exception:
        for path in reversed(written):
            path.unlink(missing_ok=True)
        raise
    print("Installed G4 + 22D. No commits, pushes, Ollama calls, network probes, or state edits.")


if __name__ == "__main__":
    main()
